import torch

# PTX source for 1D average pooling (fp16 inputs/outputs)
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry avg_pool1d_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 channels,
    .param .u32 length_in,
    .param .u32 kernel_size,
    .param .u32 stride,
    .param .u32 padding
)
{
    // Register declarations
    .reg .pred   %p<6>;
    .reg .s32    %r<31>;
    .reg .u32    %u<10>;
    .reg .u64    %rd<18>;
    .reg .f32    %f<4>;
    .reg .f16    %h<2>;

    // Load kernel parameters
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r1,  [batch];
    ld.param.u32    %r2,  [channels];
    ld.param.u32    %r3,  [length_in];
    ld.param.u32    %r4,  [kernel_size];
    ld.param.u32    %r5,  [stride];
    ld.param.u32    %r6,  [padding];

    // -------------------------------------------------
    // Compute global thread index (linear over output)
    // -------------------------------------------------
    mov.u32 %r7, %ctaid.x;          // block id
    mov.u32 %r8, %ntid.x;           // blockDim.x
    mov.u32 %r9, %tid.x;            // threadIdx.x
    mad.lo.s32 %r10, %r7, %r8, %r9; // linear thread id

    // -------------------------------------------------
    // Compute output length = (L + 2*pad - k) / stride + 1
    // -------------------------------------------------
    mul.lo.u32 %r11, %r6, 2;        // 2*padding
    add.u32 %r12, %r3, %r11;        // L + 2*pad
    sub.u32 %r13, %r12, %r4;        // - kernel
    div.u32 %r14, %r13, %r5;        // / stride
    add.u32 %r15, %r14, 1;          // +1 => out_len

    // Total number of output elements = batch * channels * out_len
    mul.lo.u32 %r16, %r1, %r2;      // batch * channels
    mul.lo.u32 %r17, %r16, %r15;    // total

    // Guard: if thread id >= total, exit
    setp.ge.u32 %p0, %r10, %r17;
    @%p0 bra EXIT;

    // -------------------------------------------------
    // Decompose linear index into (b, c, out_idx)
    // -------------------------------------------------
    // out_idx = thread % out_len
    rem.u32 %r18, %r10, %r15;
    // tmp = thread / out_len
    div.u32 %r19, %r10, %r15;
    // c = tmp % channels
    rem.u32 %r20, %r19, %r2;
    // b = tmp / channels
    div.u32 %r21, %r19, %r2;

    // Compute start index in input: start = out_idx*stride - padding
    mul.lo.u32 %r22, %r18, %r5;     // out_idx * stride
    sub.u32 %r23, %r22, %r6;        // - padding

    // -------------------------------------------------
    // Accumulate sum over kernel (fp32 accumulator)
    // -------------------------------------------------
    mov.f32 %f1, 0.0;
    .reg .s32 %k;
    mov.s32 %k, 0;

LOOP:
    setp.ge.s32 %p1, %k, %r4;      // if k >= kernel_size exit
    @%p1 bra ENDLOOP;

    // idx = start + k
    add.u32 %r24, %r23, %k;        // input index

    // Bounds check: 0 <= idx < length_in
    setp.ge.u32 %p2, %r24, %r3;    // idx >= length_in
    setp.lt.u32 %p3, %r24, 0;      // idx < 0
    or.pred %p4, %p2, %p3;         // out of bounds?
    @%p4 bra SKIP_LOAD;            // if out of bounds, skip load

    // Compute flat input offset: ((b*channels + c)*length_in + idx)
    mul.lo.u32 %r25, %r21, %r2;    // b * channels
    add.u32 %r26, %r25, %r20;      // + c
    mul.wide.u32 %rd3, %r26, %r3;  // * length_in (64bit)
    cvt.u64.u32 %rd4, %r24;        // idx as 64bit
    add.u64 %rd5, %rd3, %rd4;      // base + idx
    mul.lo.u64 %rd6, %rd5, 2;      // sizeof(fp16)=2
    add.u64 %rd7, %rd1, %rd6;      // address
    ld.global.f16 %h1, [%rd7];
    cvt.f32.f16 %f2, %h1;
    add.f32 %f1, %f1, %f2;

SKIP_LOAD:
    add.s32 %k, %k, 1;
    bra LOOP;

ENDLOOP:
    // Compute average: sum / kernel_size
    cvt.f32.u32 %f3, %r4;
    div.f32 %f1, %f1, %f3;
    cvt.rn.f16.f32 %h2, %f1;

    // Store to output:
    // offset = ((b*channels + c)*out_len + out_idx)
    mul.lo.u32 %r27, %r21, %r2;    // b * channels
    add.u32 %r28, %r27, %r20;      // + c
    mul.wide.u32 %rd8, %r28, %r15; // * out_len (64bit)
    cvt.u64.u32 %rd9, %r18;        // out_idx as 64bit
    add.u64 %rd10, %rd8, %rd9;     // base + out_idx
    mul.lo.u64 %rd11, %rd10, 2;    // *2 for fp16
    add.u64 %rd12, %rd2, %rd11;    // final address
    st.global.f16 [%rd12], %h2;

EXIT:
    ret;
}
'''

class ModelNew:
    """
    Drop‑in replacement for the PyTorch AvgPool1d model using a custom PTX kernel.
    All tensors are fp16.
    """
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, inputs):
        """
        inputs: list containing a single torch.Tensor of shape (B, C, L) dtype float16
        returns: list containing the pooled tensor of shape (B, C, L_out)
        """
        x = inputs[0]
        assert x.dtype == torch.float16, "Input must be fp16"
        B, C, L = x.shape
        ks = self.kernel_size
        st = self.stride
        pad = self.padding

        # Compute output length exactly as PyTorch does
        L_out = (L + 2 * pad - ks) // st + 1

        y = torch.empty((B, C, L_out), dtype=torch.float16, device=x.device)

        BLOCK = 256
        total_threads = B * C * L_out
        grid_x = (total_threads + BLOCK - 1) // BLOCK

        # Arguments for the PTX kernel (must be 64‑bit ints for pointers)
        args = [
            x.data_ptr(),
            y.data_ptr(),
            B,
            C,
            L,
            ks,
            st,
            pad
        ]

        ptx_launch(
            self.module,
            "avg_pool1d_kernel",
            (grid_x, 1, 1),          # grid dimensions
            (BLOCK, 1, 1),           # block dimensions
            args
        )
        return [y]
